'use client'
import { useState } from 'react'
type Vendor={id:string;status:string;storeName:string;contactName:string;phone:string;storeSlug:string;email?:string;createdAt:Date}
export function VendorManager({initialVendors}:{initialVendors:Vendor[]}){const [vendors,setVendors]=useState(initialVendors);const [message,setMessage]=useState('');async function act(id:string,action:'approve'|'reject'|'suspend'|'reactivate'){const reason=action==='reject'?window.prompt('Rejection reason (optional)')??undefined:undefined;const response=await fetch('/api/admin/vendors',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action,reason})});if(!response.ok){setMessage('The vendor action could not be completed.');return}setVendors(current=>current.map(vendor=>vendor.id===id?{...vendor,status:action==='approve'||action==='reactivate'?'approved':action==='reject'?'rejected':'suspended'}:vendor));setMessage('Vendor status updated.')}
const counts=[['Total',vendors.length],['Pending',vendors.filter(v=>v.status==='pending').length],['Approved',vendors.filter(v=>v.status==='approved').length],['Rejected',vendors.filter(v=>v.status==='rejected').length],['Suspended',vendors.filter(v=>v.status==='suspended').length]];return <><section className="mt-8 grid gap-3 sm:grid-cols-5">{counts.map(([label,value])=><article key={String(label)} className="bg-white p-4"><p className="text-sm text-[#59645f]">{label}</p><p className="mt-1 text-3xl font-bold">{value}</p></article>)}</section>{message&&<p role="status" className="mt-4 text-sm font-bold text-[#59645f]">{message}</p>}<section className="mt-6 overflow-x-auto bg-white"><table className="min-w-full text-left text-sm"><thead className="border-b"><tr><th className="p-4">Vendor</th><th className="p-4">Business</th><th className="p-4">Registered</th><th className="p-4">Status</th><th className="p-4">Actions</th></tr></thead><tbody>{vendors.map(v=><tr key={v.id} className="border-b"><td className="p-4"><strong>{v.contactName}</strong><br/><span>{v.phone}</span></td><td className="p-4">{v.storeName}</td><td className="p-4">{new Date(v.createdAt).toLocaleDateString('en-IN')}</td><td className="p-4 capitalize">{v.status}</td><td className="p-4"><div className="flex flex-wrap gap-2">{v.status==='pending'&&<button onClick={()=>act(v.id,'approve')} className="border px-3 py-2 font-bold text-green-700">Approve</button>}{v.status==='pending'&&<button onClick={()=>act(v.id,'reject')} className="border px-3 py-2 font-bold text-red-700">Reject</button>}{v.status==='approved'&&<button onClick={()=>act(v.id,'suspend')} className="border px-3 py-2 font-bold text-red-700">Suspend</button>}{v.status==='suspended'&&<button onClick={()=>act(v.id,'reactivate')} className="border px-3 py-2 font-bold text-green-700">Reactivate</button>}</div></td></tr>)}</tbody></table></section></>}
